CATALOG={key:(source,title,body) for key,source,title,body in PAGES}

def find_note(hero,z,n,mode):
    source=faction(z,n) if mode=="hunt" else mode
    if not source: return None
    chance=0.01 if mode=="hunt" else 0.05 if n%3==2 else 0.02
    owned=hero.get("found_notes",[])
    pool=[key for key,(group,_,_) in CATALOG.items() if group==source and key not in owned]
    if pool and random.random()<chance:
        key=random.choice(pool)
        hero.setdefault("found_notes",[]).append(key)
        return CATALOG[key][1]

def collection(hero,args):
    found=[key for key in reversed(hero.get("found_notes",[])) if key in CATALOG]
    def button(label,cmd): return [{"text":label,"callback_data":cmd}]
    if len(args)==1 and args[0] in found:
        key=args[0]
        _,title,body=CATALOG[key]
        return title+"\n\n"+body,[button("‹ К запискам",f"notes:p:{found.index(key)//5}")]
    page=int(args[1]) if len(args)==2 and args[0]=="p" and args[1] in tuple(map(str,range((len(found)+4)//5))) else 0
    rows=[button(CATALOG[k][1],"notes:"+k) for k in found[page*5:page*5+5]]
    if page: rows.append(button("‹ Предыдущие",f"notes:p:{page-1}"))
    if (page+1)*5<len(found): rows.append(button("Следующие ›",f"notes:p:{page+1}"))
    text=f"Найденные записки · {len(found)}/{len(CATALOG)}"
    if not found: text+="\nПока здесь пусто. Ищи письма у людей на тракте и в залах подземелий."
    rows.append(button("‹ Кодекс","nav:codex"))
    return text,rows

